import{_ as s,b as t,d as a,ah as r}from"./chunks/framework.7NXsYIIo.js";const u=JSON.parse('{"title":"Check yourself","description":"","frontmatter":{"outline":[2,3]},"headers":[],"relativePath":"node-js/tech-check/check-yourself.md","filePath":"node-js/tech-check/check-yourself.md"}'),o={name:"node-js/tech-check/check-yourself.md"};function n(i,e,c,h,l,d){return a(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="check-yourself" tabindex="-1">Check yourself <a class="header-anchor" href="#check-yourself" aria-label="Permalink to “Check yourself”">​</a></h1><p>Practise with an English-speaking technical interviewer using either Tech Check stars or Level Up career groupings. <strong>Answer one question at a time</strong>, work through hints, then agree when to continue.</p><h2 id="choose-a-prompt" tabindex="-1">Choose a prompt <a class="header-anchor" href="#choose-a-prompt" aria-label="Permalink to “Choose a prompt”">​</a></h2><ul><li><a href="./assessment-repository.html">Repository assessment prompt</a>: use here with repository access and automatic local history updates.</li><li><a href="./assessment-portable.html">Portable assessment prompt</a>: share with fellow students; includes all 193 requirements and produces a transferable save-state.</li></ul><p>Read and follow the chosen prompt in a new chat. You can supply choices immediately, for example: “Half session, Tech Check 2 stars, focused on asynchronous programming.” The interviewer asks only for missing settings, one at a time.</p><h2 id="what-to-expect" tabindex="-1">What to expect <a class="header-anchor" href="#what-to-expect" aria-label="Permalink to “What to expect”">​</a></h2><p>Choose full or half length, all eligible topics or a numbered focused-topic selection, and coached practice or strict assessment. Half sessions keep breadth with fewer questions per topic. Questions mix original coding tasks, output predictions, theory, debugging and scenarios in shuffled order.</p><p><strong>Use your IDE for coding tasks; predict output before executing tracing tasks.</strong> Coached practice offers hints and a retry or a requested full answer. Strict assessment defers feedback. Both wait for your agreement before advancing.</p><p>Strong independent answers can lead to higher-level probes. The report separates performance at your requested target from higher-level evidence, with overall and topic scores, strengths, gaps and study priorities. These are practice estimates, not official badges.</p><h2 id="history-and-resuming" tabindex="-1">History and resuming <a class="header-anchor" href="#history-and-resuming" aria-label="Permalink to “History and resuming”">​</a></h2><p>Repository sessions use <code>assessment-data/node-js-history.json</code> at the repository root. Keep separate files for different students. This directory is outside the published documentation; <strong>do not commit personal answers unintentionally</strong>.</p><p>Portable sessions return a JSON save-state to save and provide next time. Neither version assumes access to unseen chats. Say “pause” to preserve the current question and interaction, or “resume” with accessible history to continue.</p><p>Missed, skipped, hinted and revealed questions return later, mixed in without labels. New exercises revisit the same concepts, and original missed questions can also reappear. Independently solved questions give way mainly to fresh exercises.</p>',13)])])}const m=s(o,[["render",n]]);export{u as __pageData,m as default};
